const dateKey = (time:number) => new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit'}).format(time);
function distanceFor(distances:Record<string,number>,period:Period) { const today = dateKey(Date.now()); const weekday = (new Date(`${today}T12:00:00Z`).getUTCDay()+6)%7; return Object.entries(distances).reduce((sum,[day,meters]) => { const d = new Date(`${day}T12:00:00Z`); const daysAgo = Math.round((new Date(`${today}T12:00:00Z`).getTime()-d.getTime())/86400000); let valid = false; if(period==='day') valid=day===today; if(period==='week') valid=daysAgo>=0 && daysAgo < weekday+1; if(period==='weekend') valid=daysAgo>=0 && daysAgo<weekday+1 && (d.getUTCDay()===0 || d.getUTCDay()===6); if(period==='month') valid=day.slice(0,7)===today.slice(0,7); if(period==='year') valid=day.slice(0,4)===today.slice(0,4); return sum + (valid?meters:0); },0); }
const stepsFor = (distances:Record<string,number>,period:Period) => Math.floor(distanceFor(distances,period)/METERS_PER_STEP);
