 const mySteps=stepsFor(myDistances,'day');const myDistance=distanceFor(myDistances,'day'); const dayGoal=group.goals.find(g=>g.type==='day'&&g.scope==='each')?.target||group.goals.find(g=>g.type==='day'&&g.scope!=='together')?.target||group.goals.find(g=>g.type==='day')?.target||8000;
