 const raceRows=useMemo(()=>{ const ownSteps=group.members.reduce((sum,member)=>sum+stepsFor(member.distances,racePeriod),0); const ownGoal=group.goals.find(g=>g.type===racePeriod&&g.scope!=='each'); const rows=[{ id:group.id, name:group.name, steps:ownSteps, goal:ownGoal?.target||0, members:group.members.length, mine:true }, ...(group.partners||[]).map(partner=>({ id:partner.id, name:partner.name, steps:partner.steps[racePeriod]||0, goal:partner.goals.find(g=>g.type===racePeriod)?.target||0, members:partner.memberCount, mine:false }))]; return rows.sort((a,b)=>b.steps-a.steps); },[group,racePeriod]);
