 // Every goal gets its own celebration the first time it is reached in the current period.
 useEffect(()=>{ if(!state||demo||!group.id)return; const now=dateKey(Date.now()); const weekNo=(()=>{const d=new Date(`${now}T12:00:00Z`);const start=new Date(Date.UTC(d.getUTCFullYear(),0,1));return Math.ceil((((d.getTime()-start.getTime())/86400000)+start.getUTCDay()+1)/7)})(); const periodKey=(type:Period)=>type==='day'?now:type==='month'?now.slice(0,7):type==='year'?now.slice(0,4):`w${weekNo}`; let seen:Record<string,string>={}; try{seen=JSON.parse(localStorage.getItem('stride-celebrated')||'{}')||{};}catch{seen={};} const found:{id:string;type:Period;scope:GoalScope;target:number;progress:number}[]=[]; for(const goal of group.goals){ const progress=goal.scope==='each'?stepsFor(myDistances,goal.type):group.members.reduce((sum,member)=>sum+stepsFor(member.distances,goal.type),0); if(progress<goal.target)continue; const key=`${group.id}:${goal.id}:${periodKey(goal.type)}`; if(seen[key])continue; seen[key]=String(Date.now()); found.push({id:key,type:goal.type,scope:goal.scope==='each'?'each':'together',target:goal.target,progress}); } if(!found.length)return; localStorage.setItem('stride-celebrated',JSON.stringify(seen)); setCelebrations(current=>[...current,...found.filter(item=>!current.some(open=>open.id===item.id))]); },[state,group.id,group.goals,myDistances,demo]);
