 const createProfile=()=>perform(async()=>{const profileName=name.trim();if(profileName.length<3||profileName.length>32)throw new Error(t.nameHint);localStorage.setItem('stride-name',profileName);if(inviteCode){const info=await api('/invite/'+encodeURIComponent(inviteCode));const session=localStorage.getItem('stride-token')||'';const joined:Group & {token?:string}=await api('/groups/'+info.id+'/join','POST',{token:session,code:inviteCode,memberName:profileName});if(joined.token){localStorage.setItem('stride-token',joined.token);setToken(joined.token);}setState(current=>({me:{id:joined.viewerId||joined.members.at(-1)!.id,name:profileName,distances:{}},groups:[...(joined.token?[]:current?.groups||[]).filter(g=>g.id!==joined.id),joined]}));window.history.replaceState({},'',window.location.pathname);setSelected(info.id);setModal(null);notify(t.joinAction);}else{setMemberName(profileName);setModal('create');}});
