 const joinGroup=()=>perform(async()=>{let code=inviteInput.trim();try{const url=new URL(code);code=url.searchParams.get('join')||code;}catch{}const info=await api('/invite/'+encodeURIComponent(code));const alias=memberName.trim();if(alias.length<3||alias.length>32)throw new Error(t.memberName);const g:Group & {token?:string}=await api('/groups/'+info.id+'/join','POST',{token:localStorage.getItem('stride-token')||token,code,memberName:alias});if(g.token){localStorage.setItem('stride-token',g.token);setToken(g.token);}localStorage.setItem('stride-name',alias);setSelected(g.id);setState(current=>({me:g.token?{id:g.viewerId||g.members.at(-1)!.id,name:alias,distances:{}}:current?.me||{id:g.viewerId||g.members[0].id,name:alias,distances:g.members[0].distances},groups:[...(g.token?[]:current?.groups||[]).filter(x=>x.id!==g.id),g]}));setModal(null);setInviteInput('');notify(t.joinAction);});
