 const handleFix=async (pos:{coords:{accuracy:number;latitude:number;longitude:number}})=>{
 setGpsMessage(pos.coords.accuracy>40?t.gpsInaccurate:'');if(pos.coords.accuracy>40||!token)return;
 try{const now=Date.now();const previous=lastGpsFix.current;const lat=pos.coords.latitude, lon=pos.coords.longitude;lastGpsFix.current={lat,lon,at:now};if(!previous)return;const seconds=(now-previous.at)/1000;const r=Math.PI/180;const a=Math.sin((lat-previous.lat)*r/2)**2+Math.cos(previous.lat*r)*Math.cos(lat*r)*Math.sin((lon-previous.lon)*r/2)**2;const distance=12742000*Math.asin(Math.sqrt(a));if(seconds>=2&&seconds<=300&&distance>=Math.max(8,pos.coords.accuracy*.8)&&distance/seconds<=3.2){await api('/track','POST',{token,meters:distance,seconds,accuracy:pos.coords.accuracy});await refresh();}}catch(e){setGpsMessage(e instanceof Error&&e.message?e.message:t.gpsError);}};
